referenceSolutions.javascript:
export function solve(rows, key) {
  if (!rows.length) return null;
  return [rows.reduce((sum, row) => sum + row[key], 0), rows.length];
}

referenceSolutions.typescript:
type Value = any;
export function solve(rows: Value, key: Value): Value {
  if (!rows.length) return null;
  return [rows.reduce((sum: Value, row: Value) => sum + row[key], 0), rows.length];
}
